// Builds and checks every published file in this repository.
//
//   node tools/build.mjs           write the generated files
//   node tools/build.mjs --check   write nothing; fail when anything is out of date
//
// Steps:
// 1. Generate MyZenn's calm-companion tool bundle from sites/myzenn/data/support.js,
//    so the helplines a partner's visitor sees come from the same list as MyZenn's page.
// 2. Build the portable myzenn_calm network (tools/portable-network.mjs).
// 3. Build each site's own assistant with the agentify-website skill's build script.
// 4. Check that each site's runtime/ is an unchanged copy of the vendored runtime.

import { spawnSync } from "node:child_process";
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { PortableNetworkBuilder } from "./portable-network.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const VENDOR = path.join(ROOT, "vendor", "agentify-website");
const CHECK = process.argv.includes("--check");

const SITE_NETWORKS = [
  { site: "sites/myzenn", hocon: "myzenn_sanctuary.hocon" },
  { site: "sites/partner", hocon: "exam_planner.hocon" },
];

let failures = 0;

/** Step 1: the self-contained tool bundle for myzenn_calm. */
async function buildCalmTools() {
  const target = path.join(ROOT, "sites/myzenn/agents/myzenn_calm.tools.js");
  const { supportResources } = await import(pathToFileURL(path.join(ROOT, "sites/myzenn/data/support.js")).href);
  const support = supportResources();
  const text = `// GENERATED by tools/build.mjs from sites/myzenn/data/support.js. Do not edit by hand.
//
// Coded tools for MyZenn's portable myzenn_calm network. A site that loads the network
// runs this file in its own sandboxed worker, which has no network and no page access.
// The tool receives only the private-context fields its spec allows ("country"), and
// only when the calling site's own allow rule passes them. The file must stay
// self-contained, so the helpline data is written in at build time.

const SUPPORT = ${JSON.stringify(support, null, 2)};

const COUNTRY_NAMES = { IN: "India", US: "United States" };

/** Map "IN", "in" or "India" to a country name this file has lines for, else null. */
function knownCountry(value) {
  const text = String(value).trim();
  const upper = text.toUpperCase();
  if (COUNTRY_NAMES[upper]) return COUNTRY_NAMES[upper];
  return Object.values(COUNTRY_NAMES).find(name => name.toUpperCase() === upper) || null;
}

function linesFor(country) {
  const emergency = SUPPORT.emergency.find(entry => entry.country === country);
  return {
    country,
    emergency: emergency ? emergency.number : null,
    helplines: SUPPORT.helplines
      .filter(line => line.country === country)
      .map(line => ({ name: line.name, contact: line.contact, hours: line.hours })),
  };
}

export class SupportLines {
  /**
   * :param args: Unused. The tool takes no arguments.
   * :param slyData: Private context. Holds "country" only if both allow rules passed it.
   * :return: Emergency numbers and helplines, for the shared country or for each one.
   */
  invoke(args, slyData) {
    const shared = slyData && typeof slyData.country === "string" && slyData.country.trim() ? slyData.country.trim() : null;
    const directory = { label: SUPPORT.elsewhere.label, url: SUPPORT.elsewhere.url };
    if (shared) {
      const country = knownCountry(shared);
      if (country) return { countryShared: true, ...linesFor(country), directory, checkedOn: SUPPORT.checkedOn };
      return {
        countryShared: true,
        country: shared,
        emergency: null,
        helplines: [],
        note: "MyZenn lists no helplines for this country yet. Give the directory link.",
        directory,
        checkedOn: SUPPORT.checkedOn,
      };
    }
    const countries = [...new Set(SUPPORT.helplines.map(line => line.country))];
    return {
      countryShared: false,
      note: "The calling site did not share a country. Give the emergency number and one helpline for each country, and the directory link.",
      byCountry: countries.map(name => {
        const set = linesFor(name);
        return { ...set, helplines: set.helplines.slice(0, 2) };
      }),
      directory,
      checkedOn: SUPPORT.checkedOn,
    };
  }
}
`;
  let current = null;
  try {
    current = (await readFile(target, "utf8")).replace(/\r\n/g, "\n");
  } catch {
    current = null;
  }
  console.log("Calm companion tool bundle");
  if (current === text) {
    console.log("OK: up to date.\n");
    return;
  }
  if (CHECK) {
    console.log(`ERROR: ${path.relative(ROOT, target)} is out of date with data/support.js. Build without --check.\n`);
    failures += 1;
    return;
  }
  await writeFile(target, text);
  console.log(`OK: wrote ${path.relative(ROOT, target)}\n`);
}

/** Step 2: the portable network. */
async function buildCalmNetwork() {
  const builder = new PortableNetworkBuilder({
    hocon: path.join(ROOT, "sites/myzenn/agents/myzenn_calm.hocon"),
    manifest: path.join(ROOT, "sites/myzenn/agents/agent-manifest.json"),
    runtime: path.join(VENDOR, "runtime"),
    check: CHECK,
  });
  if (await builder.run()) failures += 1;
  console.log("");
}

/** Step 3: each site's own assistant, with the skill's build script. */
function buildSiteNetworks() {
  for (const { site, hocon } of SITE_NETWORKS) {
    const args = [
      path.join(VENDOR, "scripts", "build_network.mjs"),
      path.join(ROOT, site, hocon),
      "--manifest", path.join(ROOT, site, "agent-manifest.json"),
    ];
    if (CHECK) args.push("--check");
    const result = spawnSync(process.execPath, args, { encoding: "utf8" });
    process.stdout.write(result.stdout || "");
    process.stderr.write(result.stderr || "");
    if (result.status !== 0) failures += 1;
    console.log("");
  }
}

/** Step 4: every runtime copy must equal the vendored runtime, file for file. */
async function checkRuntimeCopies() {
  const source = path.join(VENDOR, "runtime");
  const files = await listFiles(source);
  console.log("Runtime copies");
  for (const { site } of SITE_NETWORKS) {
    const copy = path.join(ROOT, site, "runtime");
    let copyFiles = [];
    try {
      copyFiles = await listFiles(copy);
    } catch {
      console.log(`ERROR: ${site}/runtime is missing. Copy vendor/agentify-website/runtime there.`);
      failures += 1;
      continue;
    }
    const differ = [];
    for (const file of new Set([...files, ...copyFiles])) {
      const a = await readFile(path.join(source, file)).catch(() => null);
      const b = await readFile(path.join(copy, file)).catch(() => null);
      if (!a || !b || !a.equals(b)) differ.push(file);
    }
    if (differ.length) {
      console.log(`ERROR: ${site}/runtime differs from the vendored runtime: ${differ.join(", ")}. Do not edit runtime copies.`);
      failures += 1;
    } else {
      console.log(`OK: ${site}/runtime matches (${files.length} files).`);
    }
  }
  console.log("");
}

async function listFiles(dir, prefix = "") {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const rel = path.join(prefix, entry.name);
    if (entry.isDirectory()) out.push(...await listFiles(path.join(dir, entry.name), rel));
    else out.push(rel);
  }
  return out;
}

await buildCalmTools();
await buildCalmNetwork();
buildSiteNetworks();
await checkRuntimeCopies();
console.log(failures ? `Build ${CHECK ? "check " : ""}FAILED in ${failures} step(s).` : `Build ${CHECK ? "check " : ""}OK.`);
process.exitCode = failures ? 1 : 0;
